+  let status;
+  if (counts.failed > 0) status = 'failed';
+  else if (counts.blocked > 0) status = 'blocked';
+  else if (!ledger.entries.length) status = 'blocked';
+  else if (ledger.entries.every((e) => GREEN.includes(e.state))) status = 'green';
+  else status = 'partial';
